import Foundation
import FoundationModels

// Hand-written equivalents of what the FoundationModels macros (@Generable / @Guide)
// expand to - copied from the compiler's own expansion (swiftc -dump-macro-expansions).
// Writing them out means the app does not depend on the macro plugin, which not every
// toolchain ships (for example some Swift Playground versions on iPad).

/// Structured reply generated by the on-device model. Property order matters:
/// `reply` streams first so speech can start before the rest is generated.
struct GeneratedReply {
    var reply: String
    var errorExplanation: String
    var processExplanation: String
    var options: [String]
    var recommendation: String

    static var generationSchema: GenerationSchema {
        GenerationSchema(
            type: Self.self,
            properties: [
                GenerationSchema.Property(name: "reply", description: "The spoken reply to the user in the user's language: natural, formal, courteous, concise. No markdown.", type: String.self),
                GenerationSchema.Property(name: "errorExplanation", description: "If a task failed or could not be done, a plain explanation of the cause; otherwise an empty string.", type: String.self),
                GenerationSchema.Property(name: "processExplanation", description: "If any task or tool was used, how it was carried out step by step and whether it succeeded; otherwise an empty string.", type: String.self),
                GenerationSchema.Property(name: "options", description: "Up to three short follow-up commands the user could say next to adjust or continue, in the user's language.", type: [String].self, guides: [.maximumCount(3)]),
                GenerationSchema.Property(name: "recommendation", description: "One helpful recommendation or proposal related to those options, or an empty string.", type: String.self)
            ]
        )
    }

    var generatedContent: GeneratedContent {
        let properties: [(name: String, value: any ConvertibleToGeneratedContent)] = [
            (name: "reply", value: self.reply),
            (name: "errorExplanation", value: self.errorExplanation),
            (name: "processExplanation", value: self.processExplanation),
            (name: "options", value: self.options),
            (name: "recommendation", value: self.recommendation)
        ]
        return GeneratedContent(properties: properties, uniquingKeysWith: { _, second in second })
    }

    struct PartiallyGenerated: Identifiable, ConvertibleFromGeneratedContent {
        var id: GenerationID
        var reply: String.PartiallyGenerated?
        var errorExplanation: String.PartiallyGenerated?
        var processExplanation: String.PartiallyGenerated?
        var options: [String].PartiallyGenerated?
        var recommendation: String.PartiallyGenerated?

        init(_ content: GeneratedContent) throws {
            self.id = content.id ?? GenerationID()
            self.reply = try content.value(forProperty: "reply")
            self.errorExplanation = try content.value(forProperty: "errorExplanation")
            self.processExplanation = try content.value(forProperty: "processExplanation")
            self.options = try content.value(forProperty: "options")
            self.recommendation = try content.value(forProperty: "recommendation")
        }
    }
}

extension GeneratedReply: Generable {
    init(_ content: GeneratedContent) throws {
        self.reply = try content.value(forProperty: "reply")
        self.errorExplanation = try content.value(forProperty: "errorExplanation")
        self.processExplanation = try content.value(forProperty: "processExplanation")
        self.options = try content.value(forProperty: "options")
        self.recommendation = try content.value(forProperty: "recommendation")
    }
}

